<script setup>
import LanguageSwitcher from '../components/LanguageSwitcher.vue'
import CommunicationEventsConsole from '../components/CommunicationEventsConsole.vue'
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const $q=useQuasar(), state=ref(null), runtime=ref(null), loadError=ref(''), loading=ref(true), saving=ref(false), values=reactive({}), clearKeys=ref([]), file=ref(null), review=ref(null), importContent=ref(''), reviewing=ref(false)
const migration=reactive({destinationMongoUri:'',newRedisUrl:'',approval:'',vaultKey:'',sourcePaused:false,activation:''})
const approvalText='DADOS COPIADOS E VERIFICADOS', activationText='ATIVAR COMUNICAÇÃO AITOSOFTWARES'
const canApprove=computed(()=>state.value?.configured&&migration.approval===approvalText)
const canActivate=computed(()=>state.value?.runtimeReady&&migration.sourcePaused&&migration.activation===activationText)
const providerCategory=key=>['whatsapp_cloud','telegram','gmail'].includes(key)
const headers=()=>({headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}})
const runtimeLabel=computed(()=>({unconfigured:'Aguardando configuração',starting:'Iniciando comunicação',ready:runtime.value?.deliveryPaused?'Disponível · envios pausados':'Comunicação em execução',stopped:'Serviço parado',insufficient_resources:'Memória insuficiente',vault_key_required:'Validação do cofre pendente',error:'Falha ao iniciar'}[runtime.value?.state]||'Verificando serviço'))
const categories=computed(()=>state.value?.categories||[])
const reviewKeys=computed(()=>review.value?.keys||[])
const changed=computed(()=>Object.keys(values).filter(key=>values[key]!==''&&values[key]!==undefined).length+clearKeys.value.length)
function failure(error){$q.notify({type:'negative',message:error.response?.data?.message||'Não foi possível concluir a configuração.'})}
async function load(){loading.value=true;loadError.value='';try{const [configuration,service]=await Promise.all([api.get('/admin/communication/system',headers()),api.get('/admin/communication/system/runtime',headers()).catch(()=>null)]);state.value=configuration.data.data;runtime.value=service?.data?.data||null;for(const key of Object.keys(values))delete values[key];clearKeys.value=[]}catch(error){loadError.value=error.response?.data?.message||'Não foi possível carregar os parâmetros do serviço.';failure(error)}finally{loading.value=false}}
async function save(){saving.value=true;try{const input=Object.fromEntries(Object.entries(values).filter(([,value])=>value!==''&&value!==undefined));await api.patch('/admin/communication/system',{expectedRevision:state.value.revision,values:input,clearKeys:clearKeys.value},headers());await load();$q.notify({type:'positive',message:'Configurações protegidas salvas. Os dados anteriores não selecionados foram preservados.'})}catch(error){failure(error)}finally{saving.value=false}}
async function inspectImport(){if(!file.value)return;reviewing.value=true;try{importContent.value=await file.value.text();review.value=(await api.post('/admin/communication/system/import',{content:importContent.value,expectedRevision:state.value?.revision,dryRun:true,replace:false},headers())).data.data}catch(error){failure(error)}finally{reviewing.value=false}}
async function applyImport(){reviewing.value=true;try{await api.post('/admin/communication/system/import',{content:importContent.value,expectedRevision:state.value?.revision,dryRun:false,replace:false},headers());file.value=null;importContent.value='';review.value=null;await load();$q.notify({type:'positive',message:'Arquivo importado. Valores não incluídos foram preservados.'})}catch(error){failure(error)}finally{reviewing.value=false}}
async function restart(){saving.value=true;try{const service=(await api.post('/admin/communication/system/restart',{},headers())).data.data;await load();runtime.value=service;$q.notify({type:service.ready?'positive':service.state==='starting'?'info':'warning',message:service.ready?'Comunicação disponível.':service.error|| (service.state==='starting'?'Reinício em andamento. Atualize o estado em alguns instantes.':'O serviço não iniciou. Confira os requisitos e configurações abaixo.')})}catch(error){failure(error)}finally{saving.value=false}}
async function migrationAction(endpoint,payload,message){
  saving.value=true
  try{
    state.value=(await api.post('/admin/communication/system/'+endpoint,{expectedRevision:state.value.revision,...payload},headers())).data.data
    for(const key of Object.keys(values))delete values[key]
    clearKeys.value=[]
    $q.notify({type:'positive',message})
  }catch(error){failure(error)}finally{
    migration.destinationMongoUri='';migration.newRedisUrl='';migration.approval='';migration.vaultKey='';migration.sourcePaused=false;migration.activation='';saving.value=false
  }
}
function approveDestination(){return migrationAction('approve',{...(migration.destinationMongoUri?{destinationMongoUri:migration.destinationMongoUri.trim()}:{}),...(migration.newRedisUrl?{newRedisUrl:migration.newRedisUrl.trim()}:{}),confirmation:migration.approval},'Destino aprovado. Agora valide o cofre importado.')}
function configureVault(){return migrationAction('vault-key',{vaultKey:migration.vaultKey.trim()},'Cofre verificado e protegido. Os envios continuam pausados.')}
function activate(){return migrationAction('mode',{mode:'active',sourcePaused:migration.sourcePaused,confirmation:migration.activation},'Comunicação ativada. Aguarde o reinício controlado antes de conferir os canais.')}
function configureLocalRedis(){
  $q.dialog({title:'Configurar Redis local integrado?',message:'O Redis será iniciado junto desta instalação. A persistência AOF fica no volume desta instalação; o MongoDB mantém os registros permanentes. Para confirmar, digite CONFIGURAR REDIS LOCAL.',prompt:{model:'',type:'text',isValid:value=>value==='CONFIGURAR REDIS LOCAL'},cancel:true,persistent:true,ok:{label:'Configurar Redis local',color:'teal-7'}}).onOk(confirmation=>migrationAction('redis-local',{confirmation},'Redis local protegido configurado. Os envios continuam pausados.'))
}
function pause(){
  $q.dialog({title:'Pausar os envios da comunicação?',message:'Os processadores desta instalação serão reiniciados em modo de validação, com os novos envios pausados.',cancel:true,persistent:true,ok:{label:'Pausar envios',color:'warning'}}).onOk(()=>migrationAction('mode',{mode:'staged'},'Envios pausados. Aguarde o reinício controlado.'))
}
onMounted(load)
</script>
<template><q-layout view="hHh lpR fFf"><q-page-container><q-page class="communication-system"><div class="system-shell"><header><router-link to="/admin/comunicacao"><q-icon name="mdi-arrow-left"/>Voltar à comunicação</router-link><span>AitoSoftwares · Sistema</span><LanguageSwitcher/></header><div class="system-intro"><span class="eyebrow">CONFIGURAÇÃO PROTEGIDA</span><h1>Sistema de comunicação</h1><p>Conexões, canais e parâmetros do serviço em um só lugar. As chaves existentes nunca são exibidas de volta.</p></div><q-banner v-if="state?.mode==='staged'" rounded class="system-banner"><template #avatar><q-icon name="mdi-pause-circle-outline"/></template><strong>Migração em validação — envios pausados.</strong><div>Revise os dados e conecte o novo QR Code. A ativação dos envios será feita na etapa final da migração.</div></q-banner><q-banner v-if="state?.restartRequired" rounded class="system-restart"><template #avatar><q-icon name="mdi-restart"/></template>Há configurações salvas que precisam de um reinício controlado.<template #action><q-btn flat no-caps label="Reiniciar comunicação" :disable="!state?.runtimeReady" :loading="saving" @click="restart"/></template></q-banner><q-banner v-if="state?.pendingRequirements?.length" rounded class="system-requirements"><div v-for="(item,index) in state.pendingRequirements" :key="index">{{$ui(typeof item==='string'?item:item.message||item.key)}}</div></q-banner>
<q-linear-progress v-if="loading" indeterminate color="teal-4"/><q-banner v-if="loadError" rounded class="system-requirements">{{loadError}}<template #action><q-btn flat no-caps label="Tentar novamente" @click="load"/></template></q-banner><q-banner v-if="state&&!state.configured" rounded class="system-requirements"><strong>Configuração inicial pendente.</strong><div>Importe o arquivo .env da API e depois o arquivo do frontend, ou preencha as conexões abaixo. A chave de proteção do cofre precisa estar disponível no serviço antes da importação. Revise os requisitos indicados neste painel; a central permanece com os envios pausados durante a preparação.</div></q-banner>
<section v-if="state" class="system-runtime"><div><q-icon :name="runtime?.ready?'mdi-check-circle-outline':'mdi-server-network-outline'"/><strong>{{runtimeLabel}}</strong><q-badge v-if="state.mode" :color="state.mode==='active'?'teal-8':'blue-grey-7'" :label="state.mode==='active'?'Envios ativos':'Em validação'"/></div><p v-if="runtime&&!runtime.ready&&runtime.error">{{runtime.error}}</p><p v-else-if="!state.runtimeReady">O serviço aguarda os requisitos da migração. Salvar um arquivo não confirma a cópia dos dados.</p><div class="runtime-actions"><q-btn flat dense no-caps icon="mdi-refresh" label="Atualizar estado" :loading="loading" @click="load"/><q-btn outline dense no-caps icon="mdi-restart" label="Reiniciar serviço" :disable="!state.runtimeReady" :loading="saving" @click="restart"/></div></section>
<section v-if="state" class="system-card"><header><div><h2>Configurações por área</h2><p>Preencha somente o que deseja alterar. Deixe as chaves em branco para mantê-las.</p></div><q-btn flat round icon="mdi-refresh" aria-label="Atualizar configurações" :disable="saving" @click="load"/></header><q-expansion-item v-for="category in categories" :key="category.key" :label="$ui(category.label)" :caption="`${category.fields.length} parâmetro(s)`" :icon="category.key.includes('whatsapp')?'mdi-whatsapp':category.key==='telegram'?'mdi-telegram':category.key==='gmail'||category.key==='email'?'mdi-gmail':'mdi-tune'" class="system-category"><q-banner v-if="providerCategory(category.key)" dense rounded class="system-provider-hint">As configurações deste canal já salvas no banco têm prioridade sobre os parâmetros de ambiente. Para alterá-las, use também o formulário do canal em <router-link to="/admin/comunicacao/">Configurações da comunicação</router-link>.</q-banner><div class="system-fields"><div v-for="field in category.fields" :key="field.key" class="system-field"><q-input v-model="values[field.key]" outlined dark :label="$ui(field.label||field.key)" :type="field.sensitive?'password':'text'" :placeholder="field.sensitive?(field.configured?'Configurado · deixe vazio para manter':'Não configurado'):(field.value==null?'':String(field.value))" autocomplete="off" :disable="field.locked||saving" :hint="field.key+(field.restartRequired?' · requer reinício':'')"/><div class="system-field-status"><q-badge :color="field.configured?'teal-8':'blue-grey-7'" :label="field.locked?'Gerenciado pelo serviço':field.configured?'Configurado':'Não configurado'"/><q-checkbox dark v-if="!field.locked&&field.configured" v-model="clearKeys" :val="field.key" dense label="Remover este valor" :disable="saving" size="xs"/></div></div></div></q-expansion-item><div class="system-save"><span>{{changed}} alteração(ões) selecionada(s) · revisão {{state.revision}}</span><q-btn color="teal-7" unelevated no-caps label="Salvar configurações" icon="mdi-content-save-outline" :disable="!changed" :loading="saving" @click="save"/></div></section>
<section v-if="state?.configured" class="system-card system-migration">
<q-expansion-item label="Etapas finais da migração" icon="mdi-database-sync-outline" caption="Destino, cofre e ativação controlada" class="migration-expansion">
<div class="migration-body"><p>Estes controles confirmam uma cópia já concluída; não transferem o banco. Mantenha o NotifyFlow original funcionando até validar os dados e faça a pausa dos processadores antigos antes de ativar os novos.</p>
<div class="migration-step"><span class="migration-step-number">1</span><div><h3>Verificar banco de destino e Redis</h3><p>Use outro banco MongoDB e um Redis exclusivo. Se as conexões já foram salvas nos parâmetros de infraestrutura, deixe os campos vazios para preservá-las. Só confirme depois de comparar os dados copiados.</p>
<div class="redis-choice"><q-badge :label="state.redisMode==='local'?'Redis local integrado':state.redisMode==='external'?'Redis externo':'Redis pendente'" color="blue-grey-7"/><q-btn v-if="state.redisMode!=='local'" flat no-caps dense icon="mdi-server" label="Usar Redis local integrado" :loading="saving" @click="configureLocalRedis"/></div><q-input v-model="migration.destinationMongoUri" outlined dark type="password" autocomplete="new-password" label="MongoDB de destino (opcional se já configurado)" placeholder="mongodb+srv://..." :disable="saving"/>
<q-input v-model="migration.newRedisUrl" outlined dark type="password" autocomplete="new-password" label="Novo Redis (opcional se já configurado)" placeholder="rediss://..." :disable="saving"/>
<q-input v-model="migration.approval" outlined dark label="Digite a confirmação de conferência" :hint="approvalText" :disable="saving"/>
<q-btn unelevated no-caps color="teal-7" label="Confirmar destino verificado" :disable="!canApprove" :loading="saving" @click="approveDestination"/>
</div></div>
<div class="migration-step"><span class="migration-step-number">2</span><div><h3>Validar o cofre de credenciais</h3><p>Informe a chave Base64 de 32 bytes que abre as credenciais copiadas do WhatsApp Web. O servidor testa a abertura antes de aceitar. Trocar uma chave já registrada exige recifrar as credenciais; não gere outra chave aleatória aqui.</p>
<q-input v-model="migration.vaultKey" outlined dark type="password" autocomplete="new-password" label="Chave do cofre importado" :disable="saving"/>
<q-btn unelevated no-caps color="teal-7" label="Verificar e registrar cofre" :disable="!migration.vaultKey.trim()" :loading="saving" @click="configureVault"/>
</div></div>
<div class="migration-step"><span class="migration-step-number">3</span><div><h3>{{state.mode==='active'?'Comunicação ativa':'Ativar após o corte'}}</h3><p>Valide as conversas, os contatos, os arquivos e o novo QR Code. Então pause os processadores do NotifyFlow antigo para impedir respostas e disparos duplicados.</p>
<template v-if="state.mode!=='active'"><q-checkbox dark v-model="migration.sourcePaused" label="Confirmei a pausa dos processadores do NotifyFlow antigo" :disable="saving"/>
<q-input v-model="migration.activation" outlined dark label="Digite a confirmação de ativação" :hint="activationText" :disable="saving"/>
<p v-if="!state.runtimeReady" class="migration-warning">Resolva os requisitos pendentes apresentados acima antes da ativação.</p>
<q-btn unelevated no-caps color="teal-7" label="Ativar comunicação AitoSoftwares" :disable="!canActivate" :loading="saving" @click="activate"/>
</template><q-btn v-else outline no-caps color="amber-4" label="Pausar novos envios" :loading="saving" @click="pause"/>
</div></div></div></q-expansion-item></section>
<section class="system-card system-import"><h2>Importar configurações</h2><p>Selecione um arquivo .env para revisar os nomes das configurações antes de aplicar. As credenciais trafegam por HTTPS e são protegidas no servidor; este painel não as guarda no navegador.</p><q-file v-model="file" outlined dark accept=".env,text/plain" label="Arquivo de configuração (.env)" :max-file-size="1048576" :disable="reviewing" @update:model-value="review=null;importContent=''"/><q-btn outline no-caps color="teal-3" label="Revisar importação" class="q-mt-md" :disable="!file" :loading="reviewing" @click="inspectImport"/><div v-if="review" class="system-review"><strong>{{review.count??reviewKeys.length}} configuração(ões) encontrada(s)</strong><div class="review-keys"><q-chip v-for="key in reviewKeys" :key="typeof key==='string'?key:key.key" dense color="teal-10" text-color="teal-1">{{typeof key==='string'?key:key.key}}</q-chip></div><p v-for="note in review.notes||[]" :key="note">{{note}}</p><q-btn unelevated no-caps color="teal-7" label="Aplicar importação revisada" :loading="reviewing" @click="applyImport"/></div></section>
<CommunicationEventsConsole/></div></q-page></q-page-container></q-layout></template>
<style scoped>.communication-system{background:radial-gradient(ellipse at top right,#0d51443b,transparent 55%),#051a1b;color:#e4fcf2;padding:20px}.system-shell{max-width:1180px;margin:auto}.system-shell>header{display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:1px solid #2b5147;padding:8px 0 22px;font-size:12px;color:#94bbab}.system-shell>header>a{color:#a7edcf;text-decoration:none;display:flex;gap:8px;align-items:center}.system-intro{padding:38px 0 24px;max-width:760px}.eyebrow{font-size:10px;letter-spacing:.12em;color:#80d5b8;font-weight:800}h1{font-size:clamp(28px,4vw,43px);line-height:1.2;letter-spacing:-.035em;margin:16px 0}p{color:#a0c2b5;line-height:1.9;font-size:13px}.system-banner,.system-restart,.system-requirements{margin-bottom:18px;background:#153d35;color:#cff6e7;border:1px solid #357461;font-size:12px;line-height:1.8}.system-banner strong{display:block}.system-restart{background:#3b3219;color:#f0deae;border-color:#726038}.system-requirements{background:#432a25;color:#f4d0c1;border-color:#835047}.system-card{background:#082425;border:1px solid #2c554b;border-radius:18px;margin:20px 0;padding:24px}.system-card>header{display:flex;gap:12px;justify-content:space-between;align-items:center}.system-card h2{font-size:23px;line-height:1.4;margin:0;color:#eafff5}.system-card>header p{margin-bottom:20px}.system-category{border-top:1px solid #254a40}.system-category :deep(.q-expansion-item__container>.q-item){padding:19px 4px;font-weight:650}.system-category :deep(.q-item__label--caption){color:#91b4a4;font-size:10px;font-weight:400}.system-category :deep(.q-item__section--avatar){color:#75cdb0;min-width:40px}.system-fields{display:grid;grid-template-columns:1fr 1fr;gap:23px 18px;padding:10px 0 25px}.system-field{min-width:0}.system-field-status{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-top:10px;font-size:10px}.system-field-status :deep(.q-checkbox__label){font-size:10px;color:#9ab9ac}.system-field-status :deep(.q-badge){font-size:9px}.system-fields :deep(.q-field__label),.system-import :deep(.q-field__label){color:#b6d1c5}.system-fields :deep(.q-field__bottom){font-size:9px;line-height:1.6;overflow-wrap:anywhere;color:#8eae9f}.system-save{display:flex;gap:15px;justify-content:space-between;align-items:center;border-top:1px solid #315447;padding-top:23px}.system-save>span{font-size:11px;color:#9dc5b3}.system-import>p{max-width:800px}.system-review{margin-top:25px;border-top:1px solid #315447;padding-top:20px}.system-review>strong{font-size:14px}.review-keys{display:flex;flex-wrap:wrap;gap:4px;margin:15px 0}.review-keys :deep(.q-chip){font-size:10px;max-width:100%}.review-keys :deep(.q-chip__content){overflow-wrap:anywhere;white-space:normal}@media(max-width:650px){.communication-system{padding:13px}.system-shell>header{font-size:10px}.system-shell>header>span{display:none}.system-intro{padding:29px 0 12px}.system-card{padding:17px;border-radius:14px}.system-fields{grid-template-columns:1fr;gap:20px}.system-save{flex-direction:column;align-items:stretch}.system-card h2{font-size:20px}.system-field-status{flex-wrap:wrap}.system-review>.q-btn{width:100%;font-size:11px}}.system-provider-hint{margin:0 0 16px;background:#143c33;color:#b6decc;font-size:11px;line-height:1.8}.system-provider-hint a{color:#a0ebca}.migration-expansion :deep(.q-item){padding:0;min-height:46px}.migration-expansion :deep(.q-item__label--caption){color:#9ebbad;font-size:11px}.migration-body{padding-top:15px}.migration-step{display:grid;grid-template-columns:28px 1fr;gap:12px;border-top:1px solid #315447;padding-top:22px;margin-top:24px}.migration-step-number{display:grid;place-items:center;background:#205447;border-radius:50%;height:26px;font-size:12px;color:#c5f5df}.migration-step>div{min-width:0}.migration-step h3{font-size:17px;line-height:1.4;margin:0}.migration-step :deep(.q-field){margin-bottom:20px}.migration-step :deep(.q-field__bottom){color:#a9cdb9;font-size:10px;overflow-wrap:anywhere}.migration-step :deep(.q-checkbox){margin-bottom:16px}.migration-step :deep(.q-checkbox__label){font-size:12px;line-height:1.7;color:#c5dfd2}.migration-step :deep(.q-field__label){color:#b6d1c5}.migration-step .q-btn{font-size:12px}.migration-warning{color:#f3cf93}.system-migration{padding-bottom:18px}@media(max-width:650px){.migration-step{grid-template-columns:22px 1fr;gap:8px}.migration-step-number{height:22px;font-size:10px}.migration-step .q-btn{width:100%;font-size:11px}.migration-step h3{font-size:15px}.migration-expansion :deep(.q-item__section--avatar){min-width:32px}}
.system-runtime{border:1px solid #31584c;border-radius:14px;padding:18px 22px;margin:20px 0;background:#0d302a}.system-runtime>div:first-child{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:13px}.system-runtime>div:first-child>.q-icon{color:#8cd8b9;font-size:23px}.system-runtime .q-badge{font-size:10px;margin-left:auto}.system-runtime p{font-size:12px;margin:12px 0}.runtime-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.runtime-actions .q-btn{font-size:11px;color:#bde9d5}.system-runtime .q-btn.disabled{opacity:.45!important}@media(max-width:650px){.system-runtime{padding:17px}.system-runtime .q-badge{margin-left:0}.runtime-actions{justify-content:space-between}}
.redis-choice{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.redis-choice .q-badge{font-size:10px}.redis-choice .q-btn{color:#b6e6d1}
</style>
